const b=[640,960,1400],p=[160,320,640];function s(t){return!t.startsWith("/")||!/\.webp$/i.test(t)||/-\d+w\.webp$/i.test(t)?null:t.replace(/\.webp$/i,"")}function r(t){return/^\/images\/blog\/[\w-]+\.webp$/i.test(t)&&!/-\d+w\.webp$/i.test(t)}function o(t){return/^\/[\w-]+\.webp$/i.test(t)&&!t.includes("/images/")&&!/-\d+w\.webp$/i.test(t)}function u(t,e,a){const i=s(t);if(i&&(r(t)||o(t)))return a.map(n=>`${i}-${n}w.${e} ${n}w`).join(", ")}function w(t,e){if(r(t))return u(t,e,b)}function f(t,e){if(o(t))return u(t,e,p)}export{w as b,f as p};
